WITH unified_sales AS ( SELECT ss.ss_customer_sk AS cust_sk, c.c_customer_id, d.d_year, ss.ss_net_profit AS net_profit FROM store_sales ss INNER JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk INNER JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk UNION ALL SELECT ws.ws_bill_customer_sk AS cust_sk, c.c_customer_id, d.d_year, ws.ws_net_profit AS net_profit FROM web_sales ws INNER JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk INNER JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk ) SELECT cust_sk, c_customer_id, d_year, total_net_profit, profit_category, profit_rank FROM ( SELECT cust_sk, c_customer_id, d_year, SUM(net_profit) AS total_net_profit, CASE WHEN SUM(net_profit) >= 50000 THEN 'Platinum' WHEN SUM(net_profit) >= 20000 THEN 'Gold' ELSE 'Silver' END AS profit_category, DENSE_RANK() OVER (PARTITION BY d_year ORDER BY SUM(net_profit) DESC) AS profit_rank FROM unified_sales GROUP BY cust_sk, c_customer_id, d_year ) ranked WHERE profit_rank <= 5 ORDER BY d_year, profit_rank
